CREATE VIEW public.leaderboard AS
 SELECT p.predictor,
    count(*) AS n_forecasts,
    avg(((p.probability - (r.outcome)::numeric) ^ (2)::numeric)) AS brier_score,
    avg((- (((r.outcome)::numeric * ln(GREATEST(p.probability, 0.000000000000001))) + (((1 - r.outcome))::numeric * ln(GREATEST(((1)::numeric - p.probability), 0.000000000000001)))))) AS log_loss
   FROM (public.predictions p
     JOIN public.resolutions r ON ((r.question_id = p.question_id)))
  GROUP BY p.predictor
  ORDER BY (avg(((p.probability - (r.outcome)::numeric) ^ (2)::numeric)));


